
% Homework 5 Problem 5

%% Read image without Image Processing Toolbox
A = imread('HW5Q5_original_image.jpg');

if ndims(A) == 3
    A = double(A);
    f = 0.2989*A(:,:,1) + 0.5870*A(:,:,2) + 0.1140*A(:,:,3);
else
    f = double(A);
end

% Scale image to values between 0 and 1
f = f - min(f(:));
if max(f(:)) > 0
    f = f / max(f(:));
end

%% Projection angles
theta = 0:179;

%% Part (a): Manual Radon transform
[g, rho] = manualRadon(f, theta);

figure; %[output:32baf8e2]

subplot(1,2,1); %[output:32baf8e2]
imagesc(f); %[output:32baf8e2]
axis image off; %[output:32baf8e2]
colormap gray; %[output:32baf8e2]
title('Original Image f'); %[output:32baf8e2]

subplot(1,2,2); %[output:32baf8e2]
imagesc(theta, rho, g); %[output:32baf8e2]
axis xy; %[output:32baf8e2]
colormap gray; %[output:32baf8e2]
colorbar; %[output:32baf8e2]
xlabel('\theta (degrees)'); %[output:32baf8e2]
ylabel('\rho'); %[output:32baf8e2]
title('Sinogram g(\rho,\theta)'); %[output:32baf8e2]

%% Part (b): Manual inverse Radon transform

fRamLak = manualIRadon(g, rho, theta, size(f), 'ram-lak');
fHann = manualIRadon(g, rho, theta, size(f), 'hann');
fNone = manualIRadon(g, rho, theta, size(f), 'none');

%% Relative reconstruction errors
errorRamLak = norm(f(:) - fRamLak(:), 2) / norm(f(:), 2);
errorHann = norm(f(:) - fHann(:), 2) / norm(f(:), 2);
errorNone = norm(f(:) - fNone(:), 2) / norm(f(:), 2);

fprintf('Relative reconstruction error, Ram-Lak: %.6f\n', errorRamLak); %[output:86a58d37]
fprintf('Relative reconstruction error, Hann:    %.6f\n', errorHann); %[output:2a998725]
fprintf('Relative reconstruction error, None:    %.6f\n', errorNone); %[output:8cceb3ec]

%% Display reconstructions
figure; %[output:685e299d]

subplot(2,2,1); %[output:685e299d]
imagesc(f); %[output:685e299d]
axis image off; %[output:685e299d]
colormap gray; %[output:685e299d]
title('Original Image'); %[output:685e299d]

subplot(2,2,2); %[output:685e299d]
imagesc(fRamLak); %[output:685e299d]
axis image off; %[output:685e299d]
title(sprintf('Ram-Lak, E = %.4f', errorRamLak)); %[output:685e299d]

subplot(2,2,3); %[output:685e299d]
imagesc(fHann); %[output:685e299d]
axis image off; %[output:685e299d]
title(sprintf('Hann, E = %.4f', errorHann)); %[output:685e299d]

subplot(2,2,4); %[output:685e299d]
imagesc(fNone); %[output:685e299d]
axis image off; %[output:685e299d]
title(sprintf('No Filter, E = %.4f', errorNone)); %[output:685e299d]


%% ============================================================
% Manual Radon transform
% ============================================================

function [g, rho] = manualRadon(f, theta)

    [M, N] = size(f);

    % Coordinates centered at the middle of the image
    x = (1:N) - (N + 1)/2;
    y = (1:M) - (M + 1)/2;

    % Radius large enough to cover the full image
    R = ceil(sqrt((M/2)^2 + (N/2)^2));

    rho = -R:R;
    t = -R:R;

    g = zeros(length(rho), length(theta));

    % Create rho-t coordinate arrays
    [RHO, T] = meshgrid(rho, t);

    for k = 1:length(theta)

        ang = theta(k) * pi / 180;

        % Coordinates along each projection line
        Xq = RHO*cos(ang) - T*sin(ang);
        Yq = RHO*sin(ang) + T*cos(ang);

        % Interpolate image values along the lines
        values = interp2(x, y, f, Xq, Yq, 'linear', 0);

        % Integrate along t
        g(:,k) = sum(values, 1).';

    end
end


%% ============================================================
% Manual inverse Radon transform / filtered backprojection
% ============================================================

function fRecon = manualIRadon(g, rho, theta, imageSize, filterName)

    [numRho, numTheta] = size(g);

    %% Filter projections in the frequency domain
    if strcmpi(filterName, 'none')

        filteredG = g;

    else

        % Zero-pad projections before filtering
        L = 2^nextpow2(2*numRho);

        padBefore = floor((L - numRho)/2);
        indices = padBefore + (1:numRho);

        gPad = zeros(L, numTheta);
        gPad(indices,:) = g;

        % Frequencies in cycles per pixel
        freq = ifftshift((-L/2:L/2-1)' / L);

        % Ram-Lak ramp filter
        ramp = abs(freq);

        if strcmpi(filterName, 'ram-lak')

            filter = ramp;

        elseif strcmpi(filterName, 'hann')

            hannWindow = 0.5 * (1 + cos(2*pi*freq));
            filter = ramp .* hannWindow;

        else

            error('Unknown filter name.');

        end

        G = fft(gPad, [], 1);
        filteredPad = real(ifft(G .* filter, [], 1));

        filteredG = filteredPad(indices,:);

    end

    %% Backprojection
    M = imageSize(1);
    N = imageSize(2);

    x = (1:N) - (N + 1)/2;
    y = (1:M) - (M + 1)/2;

    [X, Y] = meshgrid(x, y);

    fRecon = zeros(M, N);

    for k = 1:numTheta

        ang = theta(k) * pi / 180;

        % Detector coordinate corresponding to each image pixel
        rhoPixel = X*cos(ang) + Y*sin(ang);

        % Interpolate the projection onto the image grid
        projectionValues = interp1(rho, filteredG(:,k), ...
                                   rhoPixel, 'linear', 0);

        fRecon = fRecon + projectionValues;

    end

    % Approximate integration over theta from 0 to pi
    fRecon = fRecon * pi / numTheta;

end


